// FUTURE ROOT-ONLY AUTHORITY BUILDER: do not run before actual native Step 5 completion.
// Execute as node --input-type=module from the repository root after writers drain.
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { planDocument, decodePlan, validatePlanProjection, composePlanProjection, planForeignResidual } from './tools/step6-plan-projection.mjs';
import { runScope } from './tools/step6-lib.mjs';
import { git, textGit, indexEntries, treeEntries } from './tools/run-commit-scope.mjs';
const root = process.cwd(), run = 'numerical-analysis-remaining-71-2026-10-17';
if (process.env.NA71_STEP5_COMPLETE !== 'owner-confirmed-after-native-close')
  throw Error('Root must first establish actual native Step 5 completion and drained writers; no engine success is inferred by this script.');
const authorization = process.env.NA71_PLAN_AUTHORIZATION;
if (typeof authorization !== 'string' || authorization.trim().length < 20)
  throw Error('Provide the actual concrete owner authorization for precisely this 142-page replacement.');
const path = 'research/plan-spec.json', authority = `research/${run}-step6-plan-projection.json`;
if (existsSync(authority)) throw Error('Archive any prior authority and its policy/evidence before issuing an honest successor; never overwrite a seal.');
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const scope = runScope(run, root), selected = new Set(scope.pages.map(row => row.id));
if (selected.size !== 142 || scope.pages.length !== 142) throw Error('Selected frontier changed; stop and review new scope.');
const manifestPaths = readdirSync('research').filter(name => name.startsWith(`${run}-batch-`)
  && /^\d+\.pages\.json$/.test(name.slice(`${run}-batch-`.length))).sort().map(name => 'research/' + name);
if (manifestPaths.length !== 71) throw Error('Expected exact 71 current canonical manifests.');
const evidencePaths = [`research/${run}-scope-ledger.json`, ...manifestPaths];
const evidenceBytes = new Map(evidencePaths.map(file => [file, readFileSync(file)]));
const original_head = textGit(root, ['--no-replace-objects', 'rev-parse', '--verify', 'HEAD']);
const headEntry = treeEntries(root, original_head).find(row => row.path === path);
const indexEntry = indexEntries(root).find(row => row.path === path);
if (!headEntry || !indexEntry || headEntry.mode !== '100644' || indexEntry.mode !== '100644'
  || indexEntry.stage !== 0 || indexEntry.flags !== '0') throw Error('Need ordinary existing HEAD/index plan blobs with no special index flags.');
const original_index_blob = indexEntry.oid;
const originalHead = decodePlan(git(root, ['--no-replace-objects', 'show', original_head + ':' + path]));
const originalIndex = decodePlan(git(root, ['--no-replace-objects', 'cat-file', 'blob', original_index_blob]));
const workingBytes = readFileSync(path), working = decodePlan(workingBytes);
const rows = text => planDocument(text).rows.filter(row => selected.has(row.id)).map(({id,raw}) => ({id,raw}));
const target_owned_rows = rows(working), page_ids = target_owned_rows.map(row => row.id);
const spec = { version: 1, kind: 'plan-page-replacement-projection', run, path,
  authorized_by: 'owner', authorization, original_head, original_index_blob, page_ids,
  base_head_owned_rows: rows(originalHead), base_index_owned_rows: rows(originalIndex), target_owned_rows,
  evidence: evidencePaths.map(file => ({path:file,sha256:sha(evidenceBytes.get(file))})) };
// Intentionally omit supporting_pages. Both new BEM helpers are on an owned page.
validatePlanProjection(spec, run, scope.pages, working, originalHead, originalIndex, root);
// Exercise the production metadata composition in memory only; no Git blob/index/tree is written.
for (const [kind, base] of [['head', originalHead], ['index', originalIndex]]) {
  const composed = composePlanProjection(base, spec, kind);
  if (planForeignResidual(composed.text, page_ids) !== planForeignResidual(base, page_ids))
    throw Error('Separate base foreign residual changed.');
}
// Detect relevant reads moving during this non-atomic builder. The native transaction
// repeats its own current-base/index/CAS protections under the normal index lock.
if (textGit(root, ['--no-replace-objects', 'rev-parse', '--verify', 'HEAD']) !== original_head
  || indexEntries(root).find(row => row.path === path)?.oid !== original_index_blob
  || !readFileSync(path).equals(workingBytes)
  || evidencePaths.some(file => !readFileSync(file).equals(evidenceBytes.get(file))))
  throw Error('Authority inputs changed during construction; drain and retry from actual current bytes.');
writeFileSync(authority, JSON.stringify(spec, null, 2) + '\n', {flag:'wx'});
const bytes = readFileSync(authority);
console.log(JSON.stringify({plan_projection:{path,authority,sha256:sha(bytes)},
  page_count:page_ids.length,evidence_count:spec.evidence.length,
  note:'Root must add only this plan_projection object to the current closeout policy while preserving its existing additional_paths and any other authorized fields.'},null,2));
